/*
 * LoRa Sender - Board 1
 * Sends simulated sensor data every 2 seconds
 * Green LED on D2 blinks on each successful transmit
 *
 * Demonstrates ALL LoRa parameters:
 *   - Frequency: 868 MHz (Europe)
 *   - Spreading Factor: SF7 (balanced range/speed)
 *   - Bandwidth: 125 kHz (default)
 *   - Coding Rate: 4/5 (minimal overhead)
 *   - TX Power: 14 dBm
 *   - CRC: Enabled for packet integrity
 */

#include <LoRa.h>

int counter = 0;
float temperature = 22.5;
float humidity = 45.0;

void setup() {
  Serial.begin(9600);
  pinMode(2, OUTPUT);

  // Initialize LoRa at 868 MHz
  if (LoRa.begin(868000000)) {
    Serial.println("[Sender] LoRa initialized!");
  } else {
    Serial.println("[Sender] LoRa init failed!");
    while (1);
  }

  // Configure LoRa parameters
  LoRa.setSpreadingFactor(7);    // SF7: balanced range & speed
  LoRa.setSignalBandwidth(125000); // 125 kHz bandwidth
  LoRa.setCodingRate4(5);        // 4/5 coding rate
  LoRa.setTxPower(14);           // 14 dBm TX power
  LoRa.setSyncWord(0x12);        // Sync word for network isolation
  LoRa.enableCrc();              // Enable CRC checking

  // Print configuration
  Serial.println("[Sender] Config: SF7 BW125k CR4/5 TxPower=14dBm");
  Serial.println("[Sender] Sending sensor data every 2s...\n");
}

void loop() {
  counter++;
  temperature = 22.5 + (counter % 10) * 0.5;
  humidity = 45.0 + (counter % 20) * 1.0;

  // Build JSON payload
  String payload = "{\"id\":" + String(counter) +
                   ",\"temp\":" + String(temperature, 1) +
                   ",\"humi\":" + String(humidity, 1) + "}";

  // Blink LED during TX
  digitalWrite(2, HIGH);

  // Send packet
  LoRa.beginPacket();
  LoRa.print(payload);
  LoRa.endPacket();

  // Print TX info with airtime estimate
  Serial.print("[Sender] TX #");
  Serial.print(counter);
  Serial.print(" | ");
  Serial.print(payload);
  Serial.println();

  digitalWrite(2, LOW);
  delay(2000);
}

