/*
 * LoRa Receiver - Board 2
 * Receives sensor data from Board 1
 * Blue LED on D2 blinks on each receive
 * Prints RSSI and SNR for signal quality analysis
 *
 * Demonstrates ALL LoRa receive features:
 *   - parsePacket() to detect incoming data
 *   - packetRssi() for signal strength
 *   - packetSnr() for signal-to-noise ratio
 *   - Streaming read for payload
 */

#include <LoRa.h>

void setup() {
  Serial.begin(9600);
  pinMode(2, OUTPUT);

  // Initialize LoRa at same frequency as sender
  if (LoRa.begin(868000000)) {
    Serial.println("[Receiver] LoRa initialized!");
  } else {
    Serial.println("[Receiver] LoRa init failed!");
    while (1);
  }

  // Must match sender configuration
  LoRa.setSpreadingFactor(7);
  LoRa.setSignalBandwidth(125000);
  LoRa.setCodingRate4(5);
  LoRa.setSyncWord(0x12);
  LoRa.enableCrc();

  // Print receive configuration
  Serial.println("[Receiver] Config: SF7 BW125k CR4/5");
  Serial.println("[Receiver] Listening for packets...\n");
}

void loop() {
  // Check for incoming packet
  int packetSize = LoRa.parsePacket();

  if (packetSize) {
    // Read payload
    String incoming = "";
    while (LoRa.available()) {
      incoming += (char)LoRa.read();
    }

    // Get signal quality metrics
    int rssi = LoRa.packetRssi();
    float snr = LoRa.packetSnr();

    // Blink LED on receive
    digitalWrite(2, HIGH);

    // Print received data with signal metrics
    Serial.print("[Receiver] RX ");
    Serial.print(packetSize);
    Serial.print("B | ");
    Serial.print(incoming);
    Serial.print(" | RSSI=");
    Serial.print(rssi);
    Serial.print("dBm SNR=");
    Serial.print(snr);
    Serial.println("dB");

    // Signal quality assessment
    if (rssi > -80) {
      Serial.println("  -> Excellent signal!");
    } else if (rssi > -100) {
      Serial.println("  -> Good signal");
    } else {
      Serial.println("  -> Weak signal, consider increasing SF or TX power");
    }
    Serial.println();

    delay(50);
    digitalWrite(2, LOW);
  }
}
